  const out: string[] = [];
  let three = 3, five = 5;
  for (let i = 1; i <= n; i++) {
    let word = "";
    if (--three === 0) { word += "Fizz"; three = 3; }
    if (--five === 0) { word += "Buzz"; five = 5; }
    out.push(word || String(i));
  }
  return out;
}

